		//#region src/client/regex-pack-library-client.ts
		/** Browser HTTP access for reusable standalone regex packs. */
		async function responseJson(response, fallback) {
			const value = await response.json();
			if (!response.ok) throw new Error(value.error ?? `${fallback}（${response.status}）`);
			return value;
		}
		/** List every reusable pack without loading expressions into the resource center. */
		async function listRegexPacks() {
			return (await responseJson(await fetch(REGEX_PACK_LIBRARY_PATH, { headers: { accept: "application/json" } }), "正则包库读取失败")).entries;
		}
		/** Import one standalone SillyTavern JSON export. */
		async function importRegexPackFile(file) {
			return (await responseJson(await fetch(`${REGEX_PACK_LIBRARY_PATH}?filename=${encodeURIComponent(file.name)}`, {
				method: "POST",
				headers: {
					accept: "application/json",
					"content-type": "application/json"
				},
				body: file
			}), "正则包导入失败")).entry;
		}
		/** Remove the reusable copy while preserving Session-owned snapshots. */
		async function deleteRegexPack(id) {
			await responseJson(await fetch(`${REGEX_PACK_LIBRARY_PATH}?id=${encodeURIComponent(id)}`, {
				method: "DELETE",
				headers: { accept: "application/json" }
			}), "正则包移除失败");
		}
		//#endregion
